import {calculateQuote,centsToMoney,rcCutoffHz,calculateTensionSet} from './calculations.js';
import {toMm,fromMm,round,calibrationCheck,tileLength,fretPositions,parseGauges,stringSpacing as calculateStringSpacing,bridgeSpacing as calculateBridgeSpacing,radiusFromChordSagitta,saddleOffsets,interpolateRadius,multiscalePlan,breakAngle,neckAnglePlan,shimThickness} from './geometry/index.js';
const $=(q,p=document)=>p.querySelector(q);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('.nav-toggle')?.addEventListener('click',e=>{const n=$('nav');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',n.classList.contains('open'))});
const num=(d,k)=>{const raw=d.get(k);if(raw==null||String(raw).trim()==='')return null;const v=Number(raw);return Number.isFinite(v)?v:null}, val=(d,k)=>String(d.get(k)||'');
const stop=`Stop if you feel abnormal resistance, hear cracking, see wood movement, find structural damage, or cannot reproduce the measurement. Consult a qualified technician for structural, fret, nut-cutting, or uncertain truss-rod work.`;
function ticket(title,confidence,checks=[],steps=[],facts=[]){return `<span class="status">${esc(confidence)}</span><h2>${esc(title)}</h2>${facts.length?`<table><tbody>${facts.map(([a,b])=>`<tr><th>${esc(a)}</th><td>${esc(b)}</td></tr>`).join('')}</tbody></table>`:''}<h3>Check this first</h3><ul>${checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Safe work order</h3><ol>${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="warning"><strong>Stop condition</strong><br>${stop}</div><div class="actions"><button type="button" data-copy>Copy result</button><button type="button" class="secondary" data-print>Print</button></div>`}
function doc(title,d,rows,sections=[]){return `<span class="status">printable record</span><h2>${esc(title)}</h2><table><tbody>${rows.filter(x=>x[1]).map(([a,b])=>`<tr><th>${esc(a)}</th><td>${esc(b)}</td></tr>`).join('')}</tbody></table>${sections.filter(x=>x[1]).map(([h,b])=>`<h3>${esc(h)}</h3><p>${esc(b).replace(/\n/g,'<br>')}</p>`).join('')}<p class="hint">Prepared as a working record, not a warranty, certification, or manufacturer document.</p><div class="actions"><button type="button" data-copy>Copy record</button><button type="button" class="secondary" data-print>Print</button></div>`}
const unitOf=d=>val(d,'geometryUnit')||'in';
const mmInput=(d,k)=>{const n=num(d,k);if(n==null)throw new RangeError(`${k} is required.`);return toMm(n,unitOf(d))};
const displayDistance=(mm,unit,places=unit==='in'?4:2)=>`${round(fromMm(mm,unit),places).toFixed(places)} ${unit}`;
const parseNumberList=(d,k,count,{asDistance=true}={})=>{const values=val(d,k).split(',').map(x=>x.trim()).filter(Boolean).map(Number);if(values.length!==count||values.some(x=>!Number.isFinite(x)))throw new RangeError(`Enter exactly ${count} comma-separated values for ${k}.`);return asDistance?values.map(x=>toMm(x,unitOf(d))):values};
function pageStyle(d,forceOrientation){const paper=val(d,'paperSize')||'A4',orientation=forceOrientation||val(d,'orientation')||'Portrait';return `<style class="dynamic-page">@page{size:${paper} ${orientation.toLowerCase()};margin:12mm}</style>`}
function calibrationPanel(d){const measured=num(d,'calibrationMeasured'),tolerance=num(d,'calibrationTolerance')??.25;let status='<span class="calibration-status fail">Calibration not verified</span><p>Measure the printed 50 mm bar before using dimensions from this output.</p>';if(measured!=null){const c=calibrationCheck(measured,50,tolerance);status=`<span class="calibration-status ${c.withinTolerance?'':'fail'}">${c.withinTolerance?'Within selected tolerance':'Outside tolerance — do not use template'}</span><p>Measured ${c.measuredMm.toFixed(2)} mm; error ${c.errorMm>=0?'+':''}${c.errorMm.toFixed(2)} mm (${c.errorPercent>=0?'+':''}${c.errorPercent.toFixed(2)}%). Correction factor reference: ${c.correctionFactor.toFixed(6)}. Reprint and verify instead of scaling cutting dimensions silently.</p>`}return `<section class="calibration"><h3>Print calibration</h3>${status}<div class="calibration-bars"><div class="calibration-bar bar-50"><span>50 mm</span></div><div class="calibration-bar bar-2in"><span>2 in / 50.8 mm</span></div></div><ul><li>Print or save at Actual size / 100%; disable Fit to page.</li><li>Check PDF viewer and printer-driver scaling, then measure both bars with a reliable ruler.</li><li>A correct browser PDF does not guarantee the physical printer avoided scaling.</li></ul></section>`}
const geometryActions=(print=true)=>`<div class="actions"><button type="button" data-copy>Copy result</button>${print?'<button type="button" class="secondary" data-print>Print</button>':''}</div>`;
const geometryError=e=>ticket('Check geometry inputs','invalid input',[e instanceof Error?e.message:String(e)],['Confirm measurement definitions and units, then run the tool again.']);
const logic={
'guitar-setup-wizard':d=>{let issue=val(d,'issue'),rel=num(d,'relief'),action=num(d,'action'),recent=val(d,'recentChange');let c=[`Confirm the ${issue.toLowerCase()} while tuned to the intended pitch.`,rel==null?'Measure relief before changing bridge height.':`Repeat the relief measurement (${rel} entered) in playing position.`,action==null?'Measure bass and treble action at a named fret.':`Verify the entered action (${action}) on both outer strings.`];if(recent!=='None')c.unshift(`Re-establish the baseline after the recent ${recent.toLowerCase()}.`);return ticket(`${issue} setup route`,'measurement-led',c,['Inspect strings, structure, hardware, and climate clues.','Measure relief, then action; do not adjust both at once.','Test every fret at normal attack.','Check pickup clearance and intonation only after geometry is stable.','Record before/after values.'])},
'fret-buzz-diagnostic':d=>{let where=val(d,'buzzWhere'),amp=val(d,'amplified'),fret=val(d,'fretCondition'),recent=val(d,'recentChange'),checks=[];if(where==='Open string')checks.push('Possible cause: nut-slot/contact point, loose hardware, or the string itself; fret the first note to isolate it.');else if(where==='Frets 1–4')checks.push('Possible cause: insufficient relief or a local fret issue; confirm relief before bridge changes.');else if(where==='Above fret 12')checks.push('Possible cause: upper-fret geometry or action; map the exact fret/string pattern.');else checks.push('Map the first and last buzzing fret on each affected string.');if(fret.includes('raised'))checks.push('Use a short straightedge/rocker only as a clue; do not automatically authorize fret leveling.');if(fret.includes('Loose'))checks.push('Stop playing and seek an in-person fret inspection.');if(amp==='No')checks.push('Acoustic rattle that is absent through the amp may be acceptable, but check loose parts and sustain.');if(recent!=='None')checks.push(`Compare against the baseline before the ${recent.toLowerCase()}.`);return ticket('Prioritized buzz investigation',fret.includes('Loose')?'technician check':'possible causes',checks,['Fit and tune stable strings.','Check loose hardware and string witness points.','Measure relief and action without changing either.','Test with normal and heavy attack through the usual signal path.','Make one reversible change, retune, and re-test.'])},
'high-action-diagnostic':d=>{let a=num(d,'action'),r=num(d,'relief'),bridge=val(d,'bridgeRoom'),first=val(d,'firstFret'),checks=[];if(r==null)checks.push('Confirm with measurement: neck relief is missing.');else checks.push(`Relief recorded: ${r} mm; compare with the instrument maker's method and baseline.`);if(a==null)checks.push('Measure action at the same named fret on bass and treble sides.');else checks.push(`Action recorded: ${a} mm; playing style and instrument type determine whether this feels high.`);if(first==='Feels high')checks.push('Possible cause: first-fret clearance; compare fretted 2nd/3rd-fret clearance before considering nut work.');if(bridge==='Near limit')checks.push('Bridge near its limit: do not infer a neck-angle repair from this alone; inspect geometry in person.');return ticket('High-action evidence map',bridge==='Near limit'?'uncertain geometry':'needs baseline',checks,['Tune and stabilize climate.','Inspect structure and neck joint.','Measure relief.','Measure action and available bridge travel.','Only then plan a reversible adjustment.'])},
'tuning-stability-troubleshooter':d=>{let drift=val(d,'drift'),bind=val(d,'binding'),strings=val(d,'stringsAge'),hw=val(d,'hardware'),checks=[];if(strings.includes('not stretched'))checks.push('Stretch and settle fresh strings, then retune repeatedly.');if(strings.includes('Old'))checks.push('Replace worn strings before diagnosing hardware.');if(bind.includes('Pings'))checks.push('Likely cause: binding or discontinuous movement at the nut/string tree; inspect fit and witness points without filing.');if(hw.includes('Loose'))checks.push('Secure only clearly identified hardware with the correct tool; do not overtighten.');if(drift==='After tremolo use')checks.push('Compare return-to-pitch direction after dips and pulls; inspect bridge balance and pivot/contact points.');return ticket('Tuning drift isolation','possible causes',checks.length?checks:['Mark string position and observe whether drift is string, tuner, nut, or bridge related.'],['Install and wind strings consistently.','Tune up to pitch and document cents of drift.','Test bends or tremolo separately.','Address one friction or hardware variable.','Re-test before intonation.'])},
'intonation-problem-diagnostic':d=>{let i=val(d,'intonation'),s=val(d,'stringsAge'),all=val(d,'allStrings'),checks=[s.includes('Old')?'Replace old strings before saddle diagnosis.':'Confirm the string is stable and precisely tuned open.',`12th-fret pattern: ${i}. Use the same fretting pressure and a precise tuner.`];if(all==='All strings similar')checks.push('A similar error across all strings can indicate measurement/fretting technique or setup geometry, not six identical saddle faults.');checks.push('Confirm relief and action first; both affect fretted pitch.');return ticket('Intonation check order','measurement required',checks,['Stabilize strings and tuning.','Compare 12th-fret harmonic and gently fretted note.','Repeat three times and record cents.','Adjust only a bridge designed for user intonation, in small reversible increments.','Retune open string after every change.'])},
'string-gauge-change-planner':d=>{let old=num(d,'oldGauge'),nu=num(d,'newGauge'),scale=num(d,'scale'),diff=old&&nu?(nu/old)**2:null,checks=[];if(!old||!nu||!scale)return ticket('Enter positive scale and gauge values','invalid input',['Gauge and scale must be finite positive numbers.'],['Correct the inputs and run again.']);checks.push(`Simple diameter-squared comparison: about ${(diff*100).toFixed(0)}% of prior tension if construction, scale, and pitch were otherwise equal.`);checks.push('Actual string tension depends on unit weight/construction; confirm with the string maker’s published data.');if(val(d,'oldTuning')!==val(d,'newTuning'))checks.push('Tuning also changes tension, so the gauge-only ratio is not the total change.');if(val(d,'tremolo').includes('tremolo'))checks.push('A floating/tremolo bridge may change balance and require a reversible spring/bridge setup.');return ticket('Gauge-change setup plan',Math.abs(1-diff)>.25?'material change':'moderate change',checks,['Record current relief, action, tremolo position, and intonation.','Install and settle the new set at intended tuning.','Re-measure relief and bridge balance.','Check nut movement without cutting.','Check action and intonation last.'],[['Gauge ratio',`${old} → ${nu}`],['Scale',`${scale} in`]])},
'alternate-tuning-string-selector':d=>{let g=num(d,'currentGauge'),semi=num(d,'semitones');if(!g||semi==null||Math.abs(semi)>12)return ticket('Check tuning inputs','invalid input',['Use a positive gauge and a pitch change between -12 and +12 semitones.'],['Correct the inputs.']);let ratio=2**(-semi/12),target=g*Math.sqrt(ratio),feel=val(d,'feel');if(feel==='Softer')target*=.95;if(feel==='Firmer')target*=1.05;return ticket('Gauge direction estimate','starting estimate',[`A similar-tension diameter estimate is ${target.toFixed(1)} (in thousandths) from a ${g} gauge at ${semi} semitones.`,`This square-root estimate assumes similar string construction; choose an available set and confirm with manufacturer unit-weight/tension data.`],['Confirm every target note and scale length.','Compare manufacturer tension data string by string.','Check nut fit without cutting.','Stabilize, then re-measure relief, action, bridge balance, and intonation.'])},
'neck-relief-measurement':d=>{let r=num(d,'relief'),u=val(d,'unit');if(r==null||r<0||r>(u==='mm'?2:.08))return ticket('Check relief measurement','invalid or extreme',['Relief must be non-negative and within a plausible measurable range. Recheck units and method.'],['Repeat the capo/last-fret measurement.']);let mm=u==='in'?r*25.4:r;let band=mm<.08?'very small':mm>.5?'large':'measurable';return ticket(`${band} recorded relief`,'comparison only',[`Converted relief: ${mm.toFixed(3)} mm / ${(mm/25.4).toFixed(4)} in.`,`A ${band} gap is not by itself an instruction to turn the truss rod. Buzz location, action, playing attack, instrument design, and manufacturer method matter.`],['Repeat three times in playing position.','Compare bass/treble string method consistently.','Record temperature/humidity and action.','Consult model-specific instructions before any adjustment.'])},
'string-action-converter':d=>{let a=num(d,'action'),u=val(d,'unit');if(a==null||a<0||a>(u==='mm'?20:.8))return ticket('Check action input','invalid or extreme',['Enter a finite, non-negative measurement and verify the unit.'],['Measure from fret crown to string underside.']);let mm=u==='in'?a*25.4:a,inch=mm/25.4,den=64,n=Math.round(inch*den);return ticket('Converted string height','exact decimal / rounded fraction',[`${mm.toFixed(3)} mm = ${inch.toFixed(4)} in ≈ ${n}/${den} in.`,`The fraction is rounded for ruler use; keep the decimal for comparisons.`],['Name the fret and string.','Measure in playing position.','Record both outer strings.'])},
'scale-length-identifier':d=>{let m=num(d,'measure'),u=val(d,'unit'),type=val(d,'measureType');if(!m||m>(u==='mm'?1000:40))return ticket('Check scale measurement','invalid input',['Enter a positive plausible distance and correct unit.'],['Measure again from the nut witness point.']);let inch=u==='mm'?m/25.4:m,scale=type.startsWith('Nut to 12')?inch*2:inch;return ticket('Estimated nominal scale','measurement estimate',[`Estimated scale: ${scale.toFixed(3)} in / ${(scale*25.4).toFixed(1)} mm.`,type.includes('bridge')?'Saddle compensation makes nut-to-saddle measurements vary by string.':'Twice nut-to-12th is a nominal scale estimate; bridge saddles sit beyond it for compensation.'],['Measure from the fretboard-side nut witness point.','Repeat along the centerline.','Compare with common model specifications, not appearance alone.'])},
'pickup-height-planner':d=>{let b=num(d,'bassGap'),t=num(d,'trebleGap'),u=val(d,'unit');if(b==null||t==null||b<0||t<0)return ticket('Check pickup measurements','invalid input',['Both gaps must be finite and non-negative.'],['Fret the last fret and measure again.']);if(u==='in'){b*=25.4;t*=25.4}let symptom=val(d,'symptom'),checks=[`Recorded clearance: bass ${b.toFixed(2)} mm, treble ${t.toFixed(2)} mm while the last fret is held.`,`Use manufacturer guidance for the exact pickup; magnets and output differ.`];if(symptom.includes('Bass side'))checks.push('Before lowering the bass side, compare clean output at equal picking force.');if(symptom.includes('Treble side'))checks.push('Before lowering the treble side, compare clean output and string-to-string balance.');if(symptom.includes('warble'))checks.push('Possible magnetic pull: increase clearance temporarily and listen for reduced warble; do not assume intonation hardware is at fault.');return ticket('Pickup balance listening plan','listening comparison',checks,['Set the amplifier clean and controls neutral.','Record present screw position and gaps.','Change one side in a small reversible increment.','Retune and compare output, attack, sustain, and warble.'])},
'electric-guitar-setup-checklist':d=>ticket('Electric setup work order','printable checklist',[`Bridge: ${val(d,'bridgeType')}. Recent change: ${val(d,'recentChange')}.`,`Available measurement tools: ${val(d,'measurements')}.`],['Inspect structure, strings, tuners, nut, and bridge.','Tune and stabilize strings.','Measure relief.','Measure action and test every fret.','Check pickup clearance and electronics.','Set intonation last; document final values.']),
'acoustic-guitar-setup-checklist':d=>{let joint=val(d,'neckJoint'),h=num(d,'humidity'),c=[`Humidity entered: ${h==null?'not measured':h+'%'}. Allow climate to stabilize before geometry decisions.`,`Neck/body observation: ${joint}.`];if(joint.includes('Gap'))c.push('Stop: movement or a crack needs qualified in-person inspection.');if(joint.includes('low saddle'))c.push('High action plus a low saddle can indicate geometry limits; do not promise a saddle-only fix.');return ticket('Acoustic setup work order',joint.includes('Gap')?'stop / inspect':'inspection first',c,['Inspect bridge, top, braces, neck joint, and cracks.','Tune and measure relief.','Measure action and saddle exposure.','Check first-fret clearance without cutting.','Document evidence before material removal.'])},
'bass-setup-checklist':d=>ticket('Bass setup work order','printable checklist',[`${val(d,'strings')} strings, ${val(d,'scale')} in scale.`,`Measurement tools: ${val(d,'measurements')}.`],['Stabilize strings at intended tuning.','Inspect neck, hardware, witness points, and bridge.','Measure relief using a consistent span.','Measure action and test each fret with normal attack.','Check pickup clearance for magnetic pull and balance.','Set intonation and record final values.']),
'used-guitar-inspection':d=>{let flags=[['Neck',val(d,'neck')],['Frets',val(d,'frets')],['Electronics',val(d,'electronics')],['Structure',val(d,'structure')]],risk=flags.filter(x=>/Concern|Heavy|Noise|Crack|Unknown|Not tested/.test(x[1])).length;return doc('Used Guitar Inspection Report',d,[['Instrument',val(d,'instrument')],['Asking price',val(d,'price')],...flags],[['Risk summary',risk?`${risk} area(s) need pricing or in-person follow-up. This report records observations and is not a warranty.`:'No concern was entered, but hidden defects remain possible.'],['Notes',val(d,'notes')]])},
'setup-measurement-sheet':d=>doc('Setup Measurement Sheet',d,[['Customer',val(d,'customer')],['Instrument',val(d,'instrumentName')],['Date',val(d,'date')],['Relief',val(d,'relief')&&`${val(d,'relief')} mm`],['Bass action',val(d,'bassAction')&&`${val(d,'bassAction')} mm`],['Treble action',val(d,'trebleAction')&&`${val(d,'trebleAction')} mm`],['Pickup—bass',val(d,'pickupBass')&&`${val(d,'pickupBass')} mm`],['Pickup—treble',val(d,'pickupTreble')&&`${val(d,'pickupTreble')} mm`]],[['Notes',val(d,'notes')]]),
'before-after-setup-card':d=>doc('Before-and-After Setup Card',d,[['Customer',val(d,'customer')],['Instrument',val(d,'instrumentName')],['Date',val(d,'date')]],[['Before',val(d,'before')],['Work performed',val(d,'work')],['After',val(d,'after')],['Notes',val(d,'notes')]]),
'guitar-condition-report':d=>doc('Guitar Condition Report',d,[['Customer',val(d,'customer')],['Instrument',val(d,'instrumentName')],['Date',val(d,'date')],['Overall condition',val(d,'condition')],['Structure',val(d,'structure')],['Electronics',val(d,'electronics')]],[['Playability',val(d,'playability')],['Notes / limitations',val(d,'notes')]]),
'guitar-repair-intake':d=>doc('Guitar Repair Intake',d,[['Customer',val(d,'customer')],['Contact',val(d,'contactInfo')],['Intake date',val(d,'intakeDate')],['Instrument',`${val(d,'brand')} ${val(d,'model')}`.trim()],['Type',val(d,'instrumentKind')],['Serial',val(d,'serial')],['Approx. year',val(d,'year')],['Strings',val(d,'strings')],['Tuning / gauge',[val(d,'currentTuning'),val(d,'stringGauge')].filter(Boolean).join(' / ')],['Case',val(d,'caseIncluded')],['Requested completion',val(d,'requestedDate')],['Budget',val(d,'budget')],['Diagnose permission',val(d,'permissionDiagnose')],['Additional-work contact',val(d,'permissionContact')]],[['Customer-reported problem',val(d,'reportedProblem')],['When it started',val(d,'issueStarted')],['Recent modifications',val(d,'recentMods')],['Visible intake damage',val(d,'visibleDamage')],['Included accessories',val(d,'accessories')],['Customer priorities',val(d,'priorities')],['Initial inspection checklist','Photograph condition; verify serial and included items; test controls at safe level; record tuning, strings, relief/action if authorized; separate customer report from technician findings.'],['Notes',val(d,'notes')]]),
'repair-quote-generator':d=>{let q;try{q=calculateQuote({laborText:val(d,'laborRows'),partsText:val(d,'partsRows'),taxPercent:num(d,'taxPercent')??0,discount:num(d,'discount')??0,deposit:num(d,'deposit')??0})}catch(e){return ticket('Check quote rows','invalid input',[e.message,'Use one item per line: Description | quantity | unit cost.'],['Correct the item rows and recalculate.'])}const cur=val(d,'currency'),fmt=c=>centsToMoney(c,cur);const lines=(title,items)=>items.length?`<h3>${title}</h3><table class="money-table"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.description)}</td><td>${x.quantity}</td><td>${fmt(Math.round(x.unitCost*100))}</td><td>${fmt(x.lineTotalCents)}</td></tr>`).join('')}</tbody></table>`:'';return `<span class="status">printable quote</span><h2>Repair Quote ${esc(val(d,'quoteNumber')||`TEMP-${val(d,'quoteDate')||'DRAFT'}`)}</h2><p>${esc(val(d,'customer'))} · ${esc(val(d,'instrumentName'))}</p>${lines('Labor',q.labor)}${lines('Parts',q.parts)}<table><tbody><tr><th>Labor subtotal</th><td>${fmt(q.laborCents)}</td></tr><tr><th>Parts subtotal</th><td>${fmt(q.partsCents)}</td></tr><tr><th>Discount</th><td>−${fmt(q.discountCents)}</td></tr><tr><th>Tax</th><td>${fmt(q.taxCents)}</td></tr><tr><th>Total</th><td><strong>${fmt(q.totalCents)}</strong></td></tr><tr><th>Deposit</th><td>−${fmt(q.depositCents)}</td></tr><tr><th>Balance due</th><td><strong>${fmt(q.balanceCents)}</strong></td></tr></tbody></table><p><strong>Estimated completion:</strong> ${esc(val(d,'estimatedCompletion')||'To be confirmed')}<br><strong>Quote validity:</strong> ${esc(val(d,'quoteValidity')||'Not stated')}</p>${val(d,'notes')?`<h3>Notes</h3><p>${esc(val(d,'notes')).replace(/\n/g,'<br>')}</p>`:''}<p class="hint">Estimate only; final scope may change after authorized diagnosis. This is not a warranty or legal approval document.</p><div class="actions"><button type="button" data-copy>Copy quote</button><button type="button" class="secondary" data-print>Print</button></div>`},
'parts-labor-job-sheet':d=>doc('Parts and Labor Job Sheet',d,[['Job number',val(d,'jobNumber')],['Customer',val(d,'customer')],['Instrument',val(d,'instrumentName')],['Technician',val(d,'technician')],['Status',val(d,'workStatus')],['Time spent',val(d,'timeSpent')],['Pickup date',val(d,'pickupDate')]],[['Diagnosis',val(d,'diagnosis')],['Work performed',val(d,'workPerformed')],['Labor entries',val(d,'laborRows')],['Parts used',val(d,'partsRows')],['Measurements before',val(d,'before')],['Measurements after',val(d,'after')],['Additional issues',val(d,'additionalIssues')],['Final test',val(d,'finalTest')],['Internal notes',val(d,'internalNotes')]]),
'customer-approval-checklist':d=>doc('Customer Approval Checklist',d,[['Customer',val(d,'customer')],['Instrument',val(d,'instrumentName')],['Approval date',val(d,'approvalDate')],['Diagnosis reviewed',val(d,'diagnosisReviewed')],['Estimated cost reviewed',val(d,'costReviewed')],['Additional work',val(d,'additionalContact')],['Replacement parts',val(d,'replacementPreference')],['Return old parts',val(d,'oldPartsReturn')],['Cosmetic risk reviewed',val(d,'cosmeticRisk')],['Notification',val(d,'notificationMethod')]],[['Custom settings / data notes',val(d,'customSettings')],['Customer notes',val(d,'notes')],['Scope note','This checklist records workflow preferences. It is not an electronic signature, waiver, contract, or warranty. Follow the shop’s actual approval process.']]),
'maintenance-schedule':d=>{const use=val(d,'usageFrequency'),gig=val(d,'gigFrequency'),env=val(d,'humidityExposure'),active=val(d,'activeElectronics')==='Yes',trem=val(d,'tremoloType'),heavy=/Daily|Multiple/.test(`${use} ${gig}`),often=/4–6|Weekly/.test(`${use} ${gig}`),stringInterval=heavy?'Every 1–3 weeks or when tone/intonation declines':often?'Every 3–8 weeks or by condition':'Every 2–6 months or by condition',checks=[['Strings',stringInterval],['After playing',val(d,'cleaningHabits')==='Wipe after playing'?'Continue wiping strings, neck, and contact areas':'Add a dry-cloth wipe to slow corrosion and buildup'],['Monthly',`Inspect tuners, jack, strap hardware, bridge fasteners, and ${trem.includes('None')?'fixed bridge':'tremolo return-to-pitch'}.`],['Seasonal',env==='Stable 40–55%'?'Record relief and action at major season changes.':`Check humidity weekly during exposure periods; record relief/action before adjusting.`],['Setup inspection',heavy?'Every 3–6 months':'Every 6–12 months, or after a gauge/tuning/climate change']];if(active)checks.splice(3,0,['Battery','Test before gigs; replace by measured condition or manufacturer interval, and remove for long storage.']);return doc('Maintenance Schedule',d,[['Instrument',val(d,'instrumentKind')],['Usage',use],['Environment',val(d,'playingEnvironment')],['Humidity exposure',env],['String type',val(d,'stringType')],['Storage',val(d,'storageMethod')],['Last setup',val(d,'lastSetup')],['Last string change',val(d,'lastStringChange')]],[...checks,['Professional check',`Book an inspection for recurring tuning/buzz, fret wear, electrical intermittency, structural movement, or any adjustment that cannot be measured safely.`]])},
'ground-hum-diagnostic':d=>{let causes=[],checks=[];if(val(d,'otherCableHum')==='Gone')causes.push('Highest priority: the original cable or connector path.');if(val(d,'otherRoomHum').startsWith('Gone'))causes.push('High priority: room EMI, lighting, power distribution, or nearby equipment.');if(val(d,'otherAmpHum')==='Gone')causes.push('High priority: the original amplifier/interface or its connected rig—service externally; do not open it.');if(val(d,'pedalboard')==='Yes')checks.push('Bypass the pedalboard with one known-good cable at low level; add devices back one at a time.');if(val(d,'looseJack')==='Yes')causes.push('Guitar-side possibility: intermittent output jack or plug contact.');if(val(d,'controlCrackle')==='Yes')causes.push('Control contamination, wear, or wiring movement may explain crackle distinct from steady hum.');if(val(d,'recentWiring')==='Yes'&&/Increases|No change/.test(val(d,'touchStringsHum')))causes.push('Guitar-side wiring/ground continuity deserves documented inspection after recent work.');if(val(d,'touchStringsHum')==='Decreases')checks.push('A decrease when touching grounded strings is common; compare its amount, pickup mode, and room before declaring a fault.');if(val(d,'pickupPositionHum').includes('Single-coil'))causes.push('Single-coil electromagnetic pickup is plausible when hum follows pickup selection.');if(val(d,'volumeZeroHum')==='Yes')checks.push('Hum remaining at guitar volume zero points attention downstream of the pickup signal: cable, pedalboard, amplifier/interface, or room.');if(!causes.length)causes.push('No single source is isolated yet; use substitution tests before opening the guitar.');return ticket('Noise-source priority',causes.length>2?'multiple clues':'isolation required',causes,[...checks,'Turn monitoring down before changing connections.','Test guitar → known-good cable → known-safe amplifier/interface.','Compare another instrument, room, and power circuit.','Document pickup/control/touch behavior before any soldering.','Stop for shock, heat, odor, damaged mains cable, or power-supply fault; never open an amplifier or mains device.'])},
'pickup-phase-troubleshooter':d=>{const thin=val(d,'thinCombined')==='Yes',drop=val(d,'volumeDropCombined')==='Yes',recent=val(d,'recentPickup')==='Yes',mismatch=val(d,'manufacturerMismatch')!=='No',checks=[];let title='Compare pickup balance before rewiring',status='possible causes';if(thin&&drop){title='Combined-position phase pattern is plausible';checks.push('Thin tone plus a marked combined-position level drop is a stronger electrical phase clue than either symptom alone.')}else if(drop)checks.push('A level drop without distinctly thin tone can come from height/output mismatch or parallel loading.');else checks.push('Without a combined-only thin/drop pattern, electrical phase is not the leading explanation.');if(recent||mismatch)checks.push('Recent replacement or mixed manufacturers increases wiring-convention uncertainty.');checks.push('Manufacturer wire colors are not universal; identify coil starts/finishes from the exact documentation.');if(val(d,'fourConductor')==='No')checks.push('Two-conductor or braided pickups may require internal modification for some corrections; do not assume accessible coil leads.');return ticket(title,status,checks,['Record pickup height and clean output for each pickup alone.','Compare the exact combined position at equal picking force.','Photograph and label every existing connection.','Verify pickup documentation and continuity/polarity with an appropriate meter method.','Have qualified soldering work performed if conductor identity remains uncertain.'])},
'pickup-wiring-selector':d=>{const four=val(d,'conductorCount').startsWith('4'),requested=[],blocked=[],hardware=[];if(val(d,'wantCoilSplit')==='Yes')(four?requested:blocked).push('Coil split');if(val(d,'wantSeriesParallel')==='Yes')(four?requested:blocked).push('Series/parallel switching');if(val(d,'wantPhaseReverse')==='Yes')(four?requested:blocked).push('Phase reverse');if(val(d,'wantKillSwitch')==='Yes')requested.push('Kill switch');if(requested.some(x=>/split|parallel|Phase/.test(x)))hardware.push('One DPDT switching section per selected coil-routing function unless a documented multi-pole scheme combines them.');if(val(d,'switchType')==='3-way toggle'&&requested.length)hardware.push('A standard 3-way pickup toggle alone cannot provide every requested auxiliary function.');const pots=num(d,'potCount')??0,tones=num(d,'toneCount')??0;if(pots<(val(d,'volumeLayout')==='Independent volumes'?2:1)+tones)blocked.push('Requested volume/tone count exceeds the entered pot count.');return ticket('Configuration feasibility',blocked.length?'constraints found':'compatible planning set',[`Available: ${requested.join(', ')||'standard pickup selection only'}.`,...(blocked.length?[`Unavailable or unresolved: ${blocked.join('; ')}.`]:['No conductor/pot-count conflict found in the entered goals.']),...hardware,'Exact switch poles and pickup color codes must come from the component documentation.'],['Draw a functional block diagram before a wire-color diagram.','Confirm conductor count, grounds/shields, pot count, and switch poles.','Choose documented switching hardware.','Photograph and continuity-test before desoldering.'])},
'potentiometer-value-selector':d=>{const active=val(d,'activePassive')==='Active',pickup=val(d,'pickupFamily'),goal=val(d,'desiredBrightness');let range,notes=[];if(active){range='Use the active-system manufacturer specification; 25kΩ is common but not universal.';notes.push('Passive pickup loading rules do not transfer directly to active electronics.')}else if(goal==='Warmer'||pickup.includes('Single'))range='Start comparison around 250kΩ; also evaluate 300kΩ or 500kΩ if the result is too dark.';else if(goal==='Brighter'||pickup==='Humbucker')range='Start comparison around 500kΩ; 1MΩ is a special-case brighter option, not a guaranteed improvement.';else range='Compare 250kΩ and 500kΩ in the actual passive circuit.';if(val(d,'cableLoad').includes('Long'))notes.push('Long/high-capacitance cable can reduce high-frequency response independently of the pot.');if(val(d,'currentSymptom')==='Too bright')notes.push('Before changing pots, compare pickup height, amplifier EQ, and cable loading.');return ticket('Pot range to compare','starting range',[range,'Higher resistance generally loads a passive pickup less; lower resistance generally loads it more.',...notes,'Pot tolerance, taper, pickup inductance/resistance, tone network, and amplifier input all affect the result.'],['Find the exact pickup/system recommendation.','Measure or identify the current pot and wiring.','Compare with the same cable and amplifier settings.','Change one component value and document the result.'])},
'tone-capacitor-comparison':d=>{const pot=num(d,'potValue'),caps=val(d,'capacitorValues').split(',').map(x=>Number(x.trim())).filter(Number.isFinite);if(!pot||pot<10||pot>2000||!caps.length||caps.some(x=>x<=0||x>500))return ticket('Check capacitor inputs','invalid input',['Enter a pot from 10–2000kΩ and comma-separated capacitor values from 0–500nF.'],['Correct the values and compare again.']);const facts=caps.map(c=>[`${c} nF`,`${rcCutoffHz(pot,c).toFixed(0)} Hz simple RC reference`]);return ticket('Capacitor comparison','relative reference',[`With the entered ${pot}kΩ resistance, larger capacitance produces a lower simple RC reference frequency and generally permits a darker tone-control minimum.`,'A passive pickup has inductance and resistance; the pot position, cable, amplifier input, and wiring mean this is not a complete guitar frequency response.'],['Compare values at the same pot position, cable, pickup height, and amplifier setting.','Use temporary, safe test connections only if qualified.','Choose by audible range and taper—not the RC number alone.'],facts)},
'series-parallel-coil-split-selector':d=>{const four=val(d,'conductorCount').startsWith('4'),sw=val(d,'availableSwitch'),options=[['Series',true,'Highest relative output / fullest tendency','Hum canceling usually retained'],['Parallel',four,'Lower output / clearer tendency','Can retain hum canceling'],['Coil split',four,'Lower output / single-coil-like tendency','Usually loses hum canceling']],available=options.filter(x=>x[1]),blocked=options.filter(x=>!x[1]);if(four&&!/DPDT|push-pull|on-on-on/i.test(sw)&&available.length>1)blocked.push(['Auxiliary switching','No documented DPDT-class switch entered','','']);return ticket('Humbucker mode options',blocked.length?'hardware limits present':'three modes available',[...available.map(x=>`${x[0]}: ${x[2]}; ${x[3]}.`),...blocked.map(x=>`${x[0]} unavailable or unresolved with the entered conductor/switch information.`),'Exact output, brightness, and hum behavior depend on pickup construction and wiring; no dB value is implied.'],['Confirm independent coil conductors and shield.','Identify coil starts/finishes from exact manufacturer documentation.','Select a switch with a documented pole/throw scheme.','Record existing wiring before soldering.'])},
'string-tension-matcher':d=>{const instrument=val(d,'tensionInstrument').startsWith('Bass')?'bass':'guitar',scale=num(d,'scale'),current=calculateTensionSet({instrument,scaleIn:scale,tuning:val(d,'currentTuning2'),gauges:val(d,'currentSet')}),target=calculateTensionSet({instrument,scaleIn:scale,tuning:val(d,'targetTuning2'),gauges:val(d,'candidateSet')});if(current.error||target.error)return ticket('Check tension inputs','invalid input',[current.error||target.error],['Use a supported scale, tuning, and p/w gauge syntax.']);const unsupported=[...current.unsupported,...target.unsupported];if(unsupported.length)return ticket('Unit-weight data unavailable','limited support',[`No published dataset entry is included for: ${[...new Set(unsupported)].join(', ')}.`,'Do not substitute diameter-only estimates for another material or construction.'],['Choose a supported D’Addario XL plain/nickel-wound gauge or consult the maker’s current tension data.']);const factor=val(d,'tensionUnit')==='N'?4.44822:1,unit=val(d,'tensionUnit'),rows=current.rows.map((r,i)=>{const t=target.rows[i],a=r.tension*factor,b=t.tension*factor;return `<tr><td>${r.string}</td><td>${esc(r.gauge)}</td><td>${a.toFixed(1)} ${unit}</td><td>${esc(t.gauge)}</td><td>${b.toFixed(1)} ${unit}</td><td>${(b-a>=0?'+':'')+(b-a).toFixed(1)} ${unit}</td></tr>`}).join(''),targetVals=target.rows.map(x=>x.tension),spread=Math.max(...targetVals)-Math.min(...targetVals),change=(target.total-current.total)/current.total*100;return `<span class="status">published unit-weight model</span><h2>Tension comparison</h2><table><thead><tr><th>String</th><th>Current gauge</th><th>Current</th><th>Candidate</th><th>Target</th><th>Difference</th></tr></thead><tbody>${rows}</tbody></table><table><tbody><tr><th>Current total</th><td>${(current.total*factor).toFixed(1)} ${unit}</td></tr><tr><th>Target total</th><td>${(target.total*factor).toFixed(1)} ${unit}</td></tr><tr><th>Total change</th><td>${change>=0?'+':''}${change.toFixed(1)}%</td></tr><tr><th>Target spread</th><td>${(spread*factor).toFixed(1)} ${unit}</td></tr></tbody></table><h3>Interpretation</h3><ul><li>${Math.abs(change)>15?'This is a material total-tension change; stabilize the instrument and recheck the full setup.':'The total change is moderate, but individual strings and bridge balance still require checking.'}</li><li>Unit weights cover only the listed D’Addario XL plain steel / nickel-plated round-wound gauges. Another brand or construction may differ.</li><li>Confirm nut movement without cutting, then recheck relief, tremolo balance, action, and intonation.</li></ul><div class="warning"><strong>Do not cut or remove material from this result.</strong> Stop for binding, abnormal resistance, structural movement, or an unsupported string.</div><div class="actions"><button type="button" data-copy>Copy result</button><button type="button" class="secondary" data-print>Print</button></div>`}
};
Object.assign(logic,{
'fret-position-template':d=>{try{const unit=unitOf(d),scale=mmInput(d,'geometryScale'),count=num(d,'fretCount'),rows=fretPositions(scale,count),reference=val(d,'measurementReference'),octave=rows.find(x=>x.fret===12),table=rows.map(x=>`<tr><td>${x.fret}</td><td>${displayDistance(x.positionMm,unit)}</td><td>${displayDistance(x.spacingMm,unit)}</td><td>${displayDistance(x.remainingMm,unit)}</td></tr>`).join('');return `${pageStyle(d)}<div class="template-output"><span class="status">12-TET coordinate table</span><h2>Fret position plan</h2><p><strong>Scale:</strong> ${displayDistance(scale,unit)} · <strong>Frets:</strong> ${rows.length} · <strong>Primary reference:</strong> ${esc(reference)}</p><p class="formula">d = s - s / 2^(n/12)</p><div class="geometry-scroll"><table class="geometry-table"><thead><tr><th>Fret</th><th>Nut to fret</th><th>Previous to fret</th><th>Remaining scale</th></tr></thead><tbody>${table}</tbody></table></div>${val(d,'printMode').startsWith('Table and')?'<h3>100 mm reference ruler</h3><div class="reference-ruler" aria-label="100 millimetre reference ruler"></div>':''}<p><strong>Fixture check:</strong> ${octave?`fret 12 = ${displayDistance(octave.positionMm,unit)}, exactly half the entered scale.`:'Add fret 12 to include the octave half-scale check.'} ${esc(val(d,'compensationNote'))}</p>${calibrationPanel(d)}<div class="warning"><strong>Verify print scale before marking material.</strong> Cumulative nut positions and adjacent spacings are different columns; do not add cumulative positions together.</div>${geometryActions(true)}</div>`}catch(e){return geometryError(e)}},
'fret-slot-print-template':d=>{try{const unit=unitOf(d),scale=mmInput(d,'geometryScale'),count=num(d,'fretCount'),stripWidth=mmInput(d,'stripWidth'),markLength=mmInput(d,'slotMarkLength'),labelEvery=num(d,'labelFrequency'),overlap=mmInput(d,'overlap'),paper=val(d,'paperSize'),orientation=val(d,'orientation'),tiling=val(d,'pageTiling'),usable={A4:{Portrait:186,Landscape:273},Letter:{Portrait:191.9,Landscape:255.4}}[paper][orientation];if(markLength>stripWidth)throw new RangeError('Slot mark length cannot exceed the template strip width.');if(!Number.isInteger(labelEvery)||labelEvery<1||labelEvery>12)throw new RangeError('Label frequency must be an integer from 1 to 12.');const frets=fretPositions(scale,count),tiles=tileLength(scale,usable,overlap),marks=[{fret:0,positionMm:0},...frets],tilingNote=tiling.startsWith('Single')&&tiles.length>1?'The entered scale exceeds one page, so registration-safe tiling is required.':'The selected page mode fits this output without a fallback.',pages=tiles.map(tile=>{const pageMarks=marks.filter(x=>x.positionMm>=tile.startMm-1e-8&&x.positionMm<=tile.endMm+1e-8).map(x=>`<i class="slot-mark" style="left:${(x.positionMm-tile.startMm).toFixed(4)}mm;height:${markLength.toFixed(4)}mm">${x.fret%labelEvery===0?`<label>${x.fret?'F'+x.fret:'NUT'}</label>`:''}</i>`).join('');return `<section class="template-page"><div class="registration"><span>PAGE ${tile.page}/${tiles.length} · START ${tile.startMm.toFixed(2)} mm</span><span>END ${tile.endMm.toFixed(2)} mm</span></div><div class="slot-strip" style="width:${tile.lengthMm.toFixed(4)}mm;height:${stripWidth.toFixed(4)}mm">${val(d,'centerline')==='Yes'?'<i class="template-centerline"></i>':''}${pageMarks}</div><p>Overlap before: ${tile.overlapBeforeMm.toFixed(1)} mm · after: ${tile.overlapAfterMm.toFixed(1)} mm. Align registration edges and confirm fret marks in the overlap.</p></section>`}).join('');return `${pageStyle(d)}<div class="template-output"><span class="status">full-scale tiled template</span><h2>Fret slot print template</h2><p>${displayDistance(scale,unit)}, ${count} frets, ${tiles.length} page(s), ${paper} ${orientation.toLowerCase()}. ${tilingNote}</p><p class="formula">Each mark uses d = s - s / 2^(n/12); pages advance by usable length minus overlap.</p>${calibrationPanel(d)}${pages}<div class="warning"><strong>Calibration not verified until measured on paper.</strong> Disable Fit to page. Do not cut slots if either bar or overlap registration exceeds the selected tolerance.</div>${geometryActions(true)}</div>`}catch(e){return geometryError(e)}},
'nut-string-spacing':d=>{try{const unit=unitOf(d),count=num(d,'stringCount'),width=mmInput(d,'nutWidth'),margin=mmInput(d,'outerMargin'),gauges=parseNumberList(d,'stringGauges',count),plan=calculateStringSpacing({count,widthMm:width,outerMarginMm:margin,gaugesMm:gauges,method:val(d,'spacingMethod'),marginMode:val(d,'marginMode')}),rows=plan.centersMm.map((center,i)=>`<tr><td>${i+1}</td><td>${displayDistance(gauges[i],unit)}</td><td>${displayDistance(center,unit)}</td><td>${i?displayDistance(plan.centerSpacingsMm[i-1],unit):'—'}</td><td>${i?displayDistance(plan.edgeGapsMm[i-1],unit):'—'}</td></tr>`).join(''),marks=plan.centersMm.map((x,i)=>`<i class="layout-mark" style="left:${x.toFixed(4)}mm"><span>${i+1}</span></i>`).join('');return `<div class="template-output"><span class="status">${esc(plan.method)} layout</span><h2>Nut string centers</h2><p>Nut width ${displayDistance(width,unit)} · left/right edge margins ${displayDistance(plan.leftEdgeMarginMm,unit)} / ${displayDistance(plan.rightEdgeMarginMm,unit)}.</p><div class="geometry-scroll"><table class="geometry-table"><thead><tr><th>String</th><th>Diameter</th><th>Center from left edge</th><th>Center spacing</th><th>Edge gap</th></tr></thead><tbody>${rows}</tbody></table></div><div class="geometry-diagram"><div class="layout-line" style="width:${width.toFixed(4)}mm">${marks}</div></div>${calibrationPanel(d)}<p>Example distinction: equal center keeps center intervals equal; equal gap changes center intervals so adjacent string edges remain equal when diameters differ.</p><div class="warning"><strong>Do not cut from calculator output alone.</strong> Confirm real string diameters, nut edge clearance, neck alignment, and printed calibration on the instrument.</div>${geometryActions(true)}</div>`}catch(e){return geometryError(e)}},
'bridge-string-spacing':d=>{try{const unit=unitOf(d),count=num(d,'bridgeStringCount'),width=mmInput(d,'bridgeWidth'),spread=mmInput(d,'outerSpread'),gauges=parseNumberList(d,'bridgeGauges',count),saddle=mmInput(d,'saddleWidth'),plan=calculateBridgeSpacing({count,bridgeWidthMm:width,outerSpreadMm:spread,gaugesMm:gauges,method:val(d,'bridgeSpacingMethod'),saddleWidthMm:saddle}),rows=plan.centersMm.map((center,i)=>`<tr><td>${i+1}</td><td>${displayDistance(center,unit)}</td><td>${i?displayDistance(plan.centerSpacingsMm[i-1],unit):'—'}</td><td>${i?displayDistance(plan.edgeGapsMm[i-1],unit):'—'}</td></tr>`).join(''),marks=plan.centersMm.map((x,i)=>`<i class="layout-mark" style="left:${x.toFixed(4)}mm"><span>S${i+1}</span></i>`).join('');return `<div class="template-output"><span class="status">measured bridge layout</span><h2>Bridge and saddle centers</h2><p>${esc(val(d,'bridgeType2'))} · footprint ${displayDistance(width,unit)} · outer-string spread ${displayDistance(spread,unit)} · saddle width ${displayDistance(saddle,unit)}.</p><div class="geometry-scroll"><table class="geometry-table"><thead><tr><th>String / saddle</th><th>Center from left edge</th><th>Center spacing</th><th>String edge gap</th></tr></thead><tbody>${rows}</tbody></table></div><div class="geometry-diagram"><div class="layout-line" style="width:${width.toFixed(4)}mm">${marks}</div></div>${calibrationPanel(d)}<p>Compare this measured bridge spread with the nut layout; the two tools use different physical references and are not interchangeable.</p><div class="warning"><strong>Reference only.</strong> Verify saddle travel, intonation direction, bridge-post location, and neck alignment before drilling or routing.</div>${geometryActions(true)}</div>`}catch(e){return geometryError(e)}},
'fretboard-radius-matcher':d=>{try{const unit=unitOf(d),chord=mmInput(d,'chordWidth'),sag=mmInput(d,'sagitta'),known=mmInput(d,'knownRadius'),mode=val(d,'radiusMeasurementMode'),endRaw=num(d,'compoundEndRadius'),end=endRaw==null?null:toMm(endRaw,unit),radius=radiusFromChordSagitta(chord,sag),delta=Math.min(.05,sag*.45),tight=radiusFromChordSagitta(chord,sag+delta),flat=radiusFromChordSagitta(chord,sag-delta),common=[7.25,9.5,10,12,14,16,20].map(x=>({inch:x,mm:x*25.4})).sort((a,b)=>Math.abs(a.mm-radius)-Math.abs(b.mm-radius)),difference=radius-known;return `<span class="status">circular-arc measurement</span><h2>Calculated radius: ${displayDistance(radius,unit)}</h2><p class="formula">R = c² / (8s) + s / 2</p><table><tbody><tr><th>Measurement mode</th><td>${esc(mode)}</td></tr><tr><th>Chord width</th><td>${displayDistance(chord,unit)}</td></tr><tr><th>Sagitta</th><td>${displayDistance(sag,unit)}</td></tr><tr><th>Nominal comparison</th><td>${displayDistance(known,unit)}</td></tr><tr><th>Difference</th><td>${displayDistance(difference,unit)}</td></tr>${end?`<tr><th>Optional compound range</th><td>${displayDistance(known,unit)} → ${displayDistance(end,unit)}; measure the longitudinal position separately.</td></tr>`:''}<tr><th>Nearest common candidate</th><td>${common[0].inch} in (${common[0].mm.toFixed(1)} mm)</td></tr></tbody></table><h3>Measurement sensitivity</h3><p>A ±${delta.toFixed(3)} mm sagitta change moves this result from ${displayDistance(tight,unit)} to ${displayDistance(flat,unit)}. Small depth errors become large radius errors.</p><div class="warning"><strong>Measurement model:</strong> chord endpoints and center depth must describe the same circular cross-section. A template/gauge observation is only a cross-check. Finish wear, strings, frets, compound geometry, and an off-center gauge can invalidate the result.</div>${geometryActions(false)}` }catch(e){return geometryError(e)}},
'saddle-radius-planner':d=>{try{const unit=unitOf(d),baseRadius=mmInput(d,'fretboardRadius'),endRadius=mmInput(d,'compoundEndRadius'),reference=mmInput(d,'compoundReferenceLength'),measurePosition=mmInput(d,'radiusMeasurePosition'),bridgePosition=mmInput(d,'bridgePosition'),count=num(d,'saddleStringCount'),spacing=mmInput(d,'stringSpacing'),actions=parseNumberList(d,'actionValues',count),gauges=parseNumberList(d,'saddleGauges',count),compound=val(d,'compoundRadius')==='Compound radius',targetRadius=compound?interpolateRadius(baseRadius,endRadius,Math.max(0,bridgePosition-measurePosition),reference):baseRadius,plan=saddleOffsets({radiusMm:targetRadius,count,spacingMm:spacing,actionsMm:actions,gaugesMm:gauges}),rows=plan.rows.map(x=>`<tr><td>${x.string}</td><td>${displayDistance(x.xMm,unit)}</td><td>${displayDistance(x.radiusRiseMm,unit)}</td><td>${displayDistance(x.actionMm,unit)}</td><td>${displayDistance(x.relativeOffsetMm,unit)}</td></tr>`).join('');return `<span class="status">relative saddle targets</span><h2>${compound?'Compound':'Constant'} radius plan</h2><p>Bridge target radius: ${displayDistance(targetRadius,unit)}. Offsets are relative to the lowest calculated string center, not material-removal amounts.</p><div class="geometry-scroll"><table class="geometry-table"><thead><tr><th>String</th><th>Center x</th><th>Radius rise</th><th>Desired action</th><th>Relative target</th></tr></thead><tbody>${rows}</tbody></table></div><p class="formula">surface rise = R - √(R² - x²); target center = rise + action + gauge/2</p><div class="warning"><strong>Do not cut saddles from these offsets.</strong> Measure actual fret plane, bridge geometry, saddle travel, string witness points, and installed action first.</div>${geometryActions(false)}` }catch(e){return geometryError(e)}},
'multiscale-fretboard-planner':d=>{try{const unit=unitOf(d),plan=multiscalePlan({trebleScaleMm:mmInput(d,'trebleScale'),bassScaleMm:mmInput(d,'bassScale'),count:num(d,'multiStringCount'),fretCount:num(d,'multiFretCount'),perpendicularFret:num(d,'perpendicularFret'),nutSpreadMm:mmInput(d,'nutSpread'),bridgeSpreadMm:mmInput(d,'bridgeSpread')}),stringRows=plan.strings.map(x=>`<tr><td>${x.string}</td><td>${displayDistance(x.scaleMm,unit)}</td><td>${displayDistance(x.nutXmm,unit)}, ${displayDistance(x.nutYmm,unit)}</td><td>${displayDistance(x.bridgeXmm,unit)}, ${displayDistance(x.bridgeYmm,unit)}</td></tr>`).join(''),fretRows=plan.frets.map(row=>`<tr><td>${row.fret}</td><td>${row.points.map(p=>`S${p.string}: ${round(fromMm(p.xMm,unit),unit==='in'?4:2)}, ${round(fromMm(p.yMm,unit),unit==='in'?4:2)}`).join(' · ')}</td></tr>`).join('');return `${pageStyle(d,'Landscape')}<span class="status">2D coordinate plan</span><h2>Multiscale fretboard coordinates</h2><p>Perpendicular fret ${plan.perpendicularFret} deviation: ${plan.perpendicularDeviationMm.toFixed(9)} mm. Nut angle ${plan.nutAngleDeg.toFixed(3)}°, bridge angle ${plan.bridgeAngleDeg.toFixed(3)}°.</p><div class="geometry-scroll"><table class="geometry-table"><thead><tr><th>String</th><th>Nominal scale</th><th>Nut x, y</th><th>Bridge x, y</th></tr></thead><tbody>${stringRows}</tbody></table><table class="coordinate-table"><thead><tr><th>Fret</th><th>Coordinates by string (x, y in ${unit})</th></tr></thead><tbody>${fretRows}</tbody></table></div><p class="formula">x(n,i) = nutX(i) + [1 - 2^(-n/12)] × scale(i); y interpolates along each string line.</p><div class="warning"><strong>Planning coordinate model.</strong> Verify centerline, edge allowance, nut/bridge hardware, perpendicular-fret convention, and a full-size drawing before cutting.</div>${geometryActions(true)}` }catch(e){return geometryError(e)}},
'neck-angle-planner':d=>{try{const unit=unitOf(d),inputs={scaleMm:mmInput(d,'geometryScale'),bodyReferenceMm:mmInput(d,'bodyReference'),bridgeHeightMm:mmInput(d,'bridgeHeight'),fretboardThicknessMm:mmInput(d,'fretboardThickness'),fretHeightMm:mmInput(d,'fretHeight'),desiredActionMm:mmInput(d,'desiredAction'),pocketDepthMm:mmInput(d,'pocketDepth'),projectionMm:mmInput(d,'projectionDistance')},plan=neckAnglePlan(inputs),low=neckAnglePlan({...inputs,bridgeHeightMm:inputs.bridgeHeightMm-1}),high=neckAnglePlan({...inputs,bridgeHeightMm:inputs.bridgeHeightMm+1});return `<span class="status">simplified projection model</span><h2>Geometric neck angle: ${plan.angleDeg.toFixed(3)}°</h2><table><tbody><tr><th>Start string plane above body reference</th><td>${displayDistance(plan.startStringPlaneMm,unit)}</td></tr><tr><th>Target bridge string plane</th><td>${displayDistance(plan.targetBridgePlaneMm,unit)}</td></tr><tr><th>Rise over projection</th><td>${displayDistance(plan.riseMm,unit)} over ${displayDistance(plan.projectionMm,unit)}</td></tr><tr><th>Projected rise over scale</th><td>${displayDistance(plan.scaleProjectionMm,unit)}</td></tr></tbody></table><p class="formula">angle = atan[(bridge plane - start string plane) / projection distance]</p><h3>Sensitivity</h3><p>A ±1 mm bridge-plane measurement changes the model from ${low.angleDeg.toFixed(3)}° to ${high.angleDeg.toFixed(3)}°.</p><div class="warning"><strong>Not a cutting authorization.</strong> Carved tops, set necks, acoustic joints, bridge travel, neck relief, top deformation, and real construction datums can fall outside this straight-line model.</div>${geometryActions(false)}` }catch(e){return geometryError(e)}},
'headstock-break-angle':d=>{try{const unit=unitOf(d),post=breakAngle(mmInput(d,'nutPostDistance'),mmInput(d,'heightDifference')),tree=breakAngle(mmInput(d,'stringTreeDistance'),mmInput(d,'stringTreeHeight')),headstock=val(d,'headstockType'),difference=tree.angleDeg-post.angleDeg;return `<span class="status">measured triangle comparison</span><h2>String break-angle comparison</h2><table><tbody><tr><th>Headstock type</th><td>${esc(headstock)}</td></tr><tr><th>Nut to post</th><td>${post.angleDeg.toFixed(2)}°</td></tr><tr><th>Nut to string tree</th><td>${tree.angleDeg.toFixed(2)}°</td></tr><tr><th>Tree comparison</th><td>${difference>=0?'+':''}${difference.toFixed(2)}°</td></tr></tbody></table><p class="formula">angle = atan(|height difference| / horizontal distance)</p><h3>How to measure</h3><p>Use the nut witness point and the string contact point on the post or tree, not hardware centers that the string does not touch. Measure in the same side-view plane.</p><div class="warning"><strong>No universal target is implied.</strong> Too little seating force may allow noise; more angle can increase friction and binding. Tuner geometry, nut material, winding, trees, and tremolo use all matter.</div>${geometryActions(false)}` }catch(e){return geometryError(e)}},
'tremolo-spring-balance':d=>{try{const instrument=val(d,'tensionInstrument').startsWith('Bass')?'bass':'guitar',set=calculateTensionSet({instrument,scaleIn:num(d,'scale'),tuning:val(d,'currentTuning2'),gauges:val(d,'currentSet')});if(set.error)throw new RangeError(set.error);if(set.unsupported.length)throw new RangeError(`Published unit-weight data unavailable for ${set.unsupported.join(', ')}.`);const current=num(d,'currentBridgeAngle'),target=num(d,'targetBridgeAngle'),springs=num(d,'springCount');if(current==null||target==null||!Number.isInteger(springs)||springs<1||springs>6)throw new RangeError('Enter bridge angles and 1–6 springs.');const direction=current>target?'Increase total spring restoring force gradually while repeatedly retuning.':current<target?'Reduce total spring restoring force gradually while repeatedly retuning.':'No bridge-angle direction change is indicated; verify after full retuning.',symmetry=val(d,'springArrangement').startsWith('Symmetric')?'Entered layout is symmetric; keep forces centered and confirm the bridge does not yaw.':'Document the mixed layout and compare a symmetric manufacturer-supported arrangement.';return `<span class="status">tension-supported observation plan</span><h2>Tremolo balance work order</h2><table><tbody><tr><th>Bridge</th><td>${esc(val(d,'bridgeType3'))}</td></tr><tr><th>Published-model string tension</th><td>${set.total.toFixed(1)} lbf / ${(set.total*4.44822).toFixed(1)} N</td></tr><tr><th>Springs</th><td>${springs}, ${esc(val(d,'springArrangement'))}</td></tr><tr><th>Bridge angle</th><td>${current.toFixed(1)}° → ${target.toFixed(1)}°</td></tr><tr><th>Claw range</th><td>${esc(val(d,'clawRange'))}</td></tr></tbody></table><h3>Adjustment direction</h3><p>${direction} ${symmetry}</p><ol><li>Record current claw distance and bridge angle.</li><li>Make one small symmetric change without counting on a fixed screw-turn formula.</li><li>Retune every string to target pitch.</li><li>Measure bridge angle again and repeat only within safe hardware travel.</li></ol><div class="warning"><strong>Stop near mechanical limits, damaged screw holes, unstable posts, or unsupported strings.</strong> Spring rate and claw motion are not inferred from string tension alone.</div>${geometryActions(false)}` }catch(e){return geometryError(e)}},
'shim-thickness-planner':d=>{try{const unit=unitOf(d),plan=shimThickness({angleDeg:num(d,'angleChange'),shimLengthMm:mmInput(d,'shimLength'),pocketLengthMm:mmInput(d,'pocketLength')});return `<span class="status">taper geometry comparison</span><h2>Shim thickness difference</h2><table><tbody><tr><th>Angle change</th><td>${plan.angleDeg.toFixed(3)}°</td></tr><tr><th>Entered shim length</th><td>${displayDistance(plan.shimLengthMm,unit)}</td></tr><tr><th>Thickness difference over entered length</th><td>${displayDistance(plan.shortShimDifferenceMm,unit)}</td></tr><tr><th>Full pocket length</th><td>${displayDistance(plan.pocketLengthMm,unit)}</td></tr><tr><th>Full-pocket thickness difference</th><td>${displayDistance(plan.fullPocketDifferenceMm,unit)}</td></tr></tbody></table><p class="formula">thickness difference = tan(angle) × covered length</p><p>A full-pocket tapered shim supports the intended contact area more predictably than using this result to improvise a small card or partial wedge.</p><div class="warning"><strong>Geometry only.</strong> Pocket flatness, fastener engagement, neck construction, bridge travel, and the direction of the required correction need physical inspection.</div>${geometryActions(false)}` }catch(e){return geometryError(e)}}
});
const area=$('.workspace[data-tool]');if(area){const form=$('form',area),result=$('.result',area),slug=area.dataset.tool;form.addEventListener('submit',e=>{e.preventDefault();try{result.innerHTML=logic[slug](new FormData(form));bind()}catch(err){result.innerHTML=ticket('Tool error','input error',['Review the entered values and try again.'],['Reset the form.']);console.error(err)}});form.addEventListener('reset',()=>setTimeout(()=>{result.innerHTML='<p class="eyebrow">Result ticket</p><h2>Ready for measurements</h2><p>Complete the inputs, then run the tool.</p>'}));}
function bind(){const r=$('.result');$('[data-copy]',r)?.addEventListener('click',async e=>{const button=e.currentTarget;try{await navigator.clipboard.writeText(r.innerText);button.textContent='Copied'}catch{button.textContent='Select and copy manually'}});$('[data-print]',r)?.addEventListener('click',()=>window.print())}
